#!/bin/sh
# pre-commit dispatcher — generated by atlasctl. Do not edit: it is replaced on
# every installation. Adopter guards belong in guards.d/ and run without
# touching this file.
#
# It first runs the base-branch guard, then every executable guard in guards.d/
# in lexicographic order, aborting at the first failure.

case "$0" in
    */*) hooks_dir=${0%/*} ;;
    *) hooks_dir=. ;;
esac

spec_root={{SPEC_ENGINE_ROOT}}

warn() {
    echo "⚠️  pre-commit: $1"
}

if ! git rev-parse --verify --quiet HEAD >/dev/null 2>&1; then
    warn "no commits yet, so there is no base branch to protect. Commit allowed."
    base=-
else
    branch=$(git symbolic-ref --quiet --short HEAD 2>/dev/null || true)
    if [ -z "$branch" ]; then
        warn "detached HEAD, so there is no base branch to protect. Commit allowed."
        base=-
    else
        base=$(git symbolic-ref --quiet --short refs/remotes/origin/HEAD 2>/dev/null || true)
        base=${base#origin/}
        if [ -z "$base" ]; then
            if git show-ref --verify --quiet refs/heads/main; then
                base=main
            elif git show-ref --verify --quiet refs/heads/master; then
                base=master
            fi
        fi
        if [ -z "$base" ]; then
            warn "could not determine the base branch (no origin/HEAD, main or master). Commit allowed."
        fi
    fi
fi

if [ -n "$base" ] && [ "$base" != "-" ] && [ "$branch" = "$base" ]; then
    change=""
    if [ -n "$spec_root" ]; then
        change=$(git diff --cached --name-only | while IFS= read -r path; do
            rest=${path#"$spec_root"/changes/}
            if [ "$rest" != "$path" ]; then
                name=${rest%%/*}
                if [ "$name" != "$rest" ]; then
                    printf '%s\n' "$name"
                    break
                fi
            fi
        done)
    fi

    echo "❌ Commit blocked: you are on the base branch '$base'."
    if [ -n "$change" ]; then
        echo "   The artifacts of change '$change' are staged on the base branch."
        echo "   Isolate the change in its worktree and commit from there:"
        echo ""
        echo "     git worktree add \".worktrees/$change\" -b \"feature/$change\""
        echo "     cd \".worktrees/$change\""
        echo ""
        echo "   Then run the commit again."
    else
        echo "   Changes are never committed on the base branch; it only receives merges."
        echo "   Work on a feature branch and open a pull request:"
        echo ""
        echo "     git checkout -b feature/<change>"
        echo ""
        echo "   Then commit, push and open the pull request."
    fi
    exit 1
fi

guards="$hooks_dir/guards.d"
[ -d "$guards" ] || exit 0

for guard in "$guards"/*; do
    [ -f "$guard" ] || continue
    name=${guard##*/}
    if [ ! -x "$guard" ]; then
        echo "⚠️  pre-commit: skipping non-executable guard '$name'."
        continue
    fi
    if ! "$guard"; then
        echo "❌ pre-commit: guard '$name' failed; commit aborted."
        exit 1
    fi
done

exit 0
